import { BreakpointObserver, BreakpointState } from '@angular/cdk/layout';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  ElementRef,
  HostBinding,
  HostListener,
  inject,
  Input,
  ViewEncapsulation,
} from '@angular/core';
import { injectDestroy } from '@questrade/allspark-angular-components/core/utils';
import { takeUntil } from 'rxjs';
import { QDialogClosedBy } from './types/dialog-closedby.type';
import { QDialogSize } from './types/dialog-size.type';

@Component({
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  selector: 'dialog[q-dialog], dialog[qDialog]',
  template: '<ng-content />',
  styleUrl: './dialog.component.scss',
})
export class QDialogComponent implements AfterViewInit {
  @Input() size: QDialogSize | null = null;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-dialog';
  @Input() @HostBinding('attr.closedby') closedby: QDialogClosedBy | null = null;

  @HostBinding('class') get _hostClasses(): string {
    return ['q-dialog', this.size && `q-dialog-${this.size}`].filter(Boolean).join(' ');
  }

  @HostListener('mousedown', ['$event']) _onClick = (event: MouseEvent): void =>
    this._handleClickOutside(event);

  @HostListener('keydown.escape', ['$event']) _onEscapeKeydown = (event: KeyboardEvent): void =>
    this._handleEscapeKeydown(event);

  private readonly _destroy$ = injectDestroy();
  private readonly _elementRef = inject(ElementRef);
  private readonly _dialogElement: HTMLDialogElement = this._elementRef.nativeElement;
  private readonly _breakpointObserver = inject(BreakpointObserver);
  private readonly _cdr = inject(ChangeDetectorRef);

  ngAfterViewInit(): void {
    this._observeBreakpoints();
  }

  showModal(): void {
    this._dialogElement.showModal();
  }

  close(returnValue?: string): void {
    this._dialogElement.close(returnValue);
  }

  private _observeBreakpoints(): void {
    if (!this.size) {
      return;
    }

    const initialSize = this.size;
    const sizeOrder: QDialogSize[] = ['medium', 'large', 'xlarge'];
    const breakpointMap = new Map<string, QDialogSize>([
      ['(max-width: 723px)', 'medium'],
      ['(min-width: 724px) and (max-width: 1279px)', 'large'],
      ['(min-width: 1280px)', 'xlarge'],
    ]);
    const breakpointOrder: string[] = [
      '(max-width: 723px)',
      '(min-width: 724px) and (max-width: 1279px)',
      '(min-width: 1280px)',
    ];

    this._breakpointObserver
      .observe(breakpointOrder)
      .pipe(takeUntil(this._destroy$))
      .subscribe((state: BreakpointState) => {
        let potentialSize = initialSize;

        for (const breakpoint of breakpointOrder) {
          if (state.breakpoints[breakpoint]) {
            potentialSize = breakpointMap.get(breakpoint) || initialSize;
            break;
          }
        }

        const initialSizeIndex = sizeOrder.indexOf(initialSize);
        const potentialSizeIndex = sizeOrder.indexOf(potentialSize);

        // The new size should be the smaller of the two (based on index)
        // If initialSize is 'medium' (index 0), it can never be larger.
        // If initialSize is 'large' (index 1), it can be 'medium' or 'large'.
        // If initialSize is 'xlarge' (index 2), it can be 'medium', 'large', or 'xlarge'.
        const newSizeIndex = Math.min(initialSizeIndex, potentialSizeIndex);
        const newSize = sizeOrder[newSizeIndex];

        if (newSize && this.size !== newSize) {
          this.size = newSize;
          this._cdr.markForCheck();
        }
      });
  }

  private _handleClickOutside(event: MouseEvent): void {
    if (['none', 'closerequest'].includes(this.closedby || '')) {
      event.preventDefault();
      return;
    }

    const target = event.target as HTMLElement;
    const rect = this._dialogElement.getBoundingClientRect();
    const isInDialog =
      rect.top <= event.clientY &&
      event.clientY <= rect.top + rect.height &&
      rect.left <= event.clientX &&
      event.clientX <= rect.left + rect.width;

    if (!isInDialog && target === this._dialogElement) {
      this._dialogElement.close();
    }
  }

  private _handleEscapeKeydown(event: KeyboardEvent): void {
    if (this.closedby === 'none') {
      event.preventDefault();
    }
  }
}
